function vox(t,f0,f1,dur,vol,form){const a=AC;const o=a.createOscillator();o.type='sawtooth';o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(f1,t+dur);
  const vib=a.createOscillator();vib.frequency.value=5.5;const vg=a.createGain();vg.gain.value=f0*.035;vib.connect(vg).connect(o.frequency);
  const rough=a.createOscillator();rough.frequency.value=27;const rg=a.createGain();rg.gain.value=.4;const am=a.createGain();am.gain.value=.6;rough.connect(rg).connect(am.gain);
  const env=a.createGain();env.gain.setValueAtTime(0,t);env.gain.linearRampToValueAtTime(vol,t+.07);env.gain.setValueAtTime(vol*.8,t+dur*.7);env.gain.linearRampToValueAtTime(0,t+dur);
  o.connect(am);for(const [fq,q,gv] of form){const bp=a.createBiquadFilter();bp.type='bandpass';bp.frequency.setValueAtTime(fq,t);bp.frequency.linearRampToValueAtTime(fq*.75,t+dur);bp.Q.value=q;const g=a.createGain();g.gain.value=gv;am.connect(bp).connect(g).connect(env)}
  env.connect(MASTER);[o,vib,rough].forEach(x=>{x.start(t);x.stop(t+dur+.05)})}
