function gvMuzzle(){const L=GV.veh[0];const xa=L.x-36.5,xb=L.x+36.5,a=Math.atan2(gvG(xb)-gvG(xa),73);const cx=L.x,cy=(gvG(xa)+gvG(xb))/2-GWR;const lx=(450-GOX)*GK,ly=(16-GOY)*GK;return {x:cx+lx*Math.cos(a)-ly*Math.sin(a),y:cy+lx*Math.sin(a)+ly*Math.cos(a)}}
