    x.save();x.translate(W/2,H*.2);x.rotate(-.04);x.textAlign='center';x.fillStyle='rgba(230,225,200,.07)';x.font='900 46px Anton, Impact, sans-serif';x.fillText('ÜTEGKASSZA',0,0);x.font='900 16px Anton, Impact, sans-serif';x.fillText('TÜZÉROSZTÁLY · HADTÁP · BIZALMAS',0,24);x.restore();
