  // figyelmeztető sárga-fekete csík felül
  c.save();c.beginPath();c.rect(0,0,W,9);c.clip();c.fillStyle='#e8b923';c.fillRect(0,0,W,9);c.fillStyle='#14140f';const sh=(now/40)%24;for(let x=-24+sh;x<W+24;x+=24){c.beginPath();c.moveTo(x,0);c.lineTo(x+12,0);c.lineTo(x+3,9);c.lineTo(x-9,9);c.fill()}c.restore();c.fillStyle='rgba(0,0,0,.5)';c.fillRect(0,9,W,2);
