// ---- hang: csilingelés, kassza, kaszinós lounge-zene ----
function tkJingle(den,crit){if(!SOUND||!ac())return;const a=AC,t=a.currentTime;
  const tone=(f,tt,v,d,lp)=>{const o=a.createOscillator(),g=a.createGain(),fl=a.createBiquadFilter();o.type='sine';o.frequency.value=f;fl.type='lowpass';fl.frequency.value=lp||2200;g.gain.setValueAtTime(.0001,tt);g.gain.exponentialRampToValueAtTime(v,tt+.006);g.gain.exponentialRampToValueAtTime(.0001,tt+d);o.connect(fl).connect(g).connect(MASTER);o.start(tt);o.stop(tt+d+.05)};
  const noise=(tt,f,q,v,d,type)=>{const n=a.createBufferSource();n.buffer=NOISE;const fl=a.createBiquadFilter();fl.type=type||'bandpass';fl.frequency.value=f;fl.Q.value=q;const g=a.createGain();g.gain.setValueAtTime(.0001,tt);g.gain.exponentialRampToValueAtTime(v,tt+.008);g.gain.exponentialRampToValueAtTime(.0001,tt+d);n.connect(fl).connect(g).connect(MASTER);n.start(tt,Math.random()*.6,d+.05)};
  const P5=[523.25,587.33,659.25,783.99,880];
  if(TK_DEN[den].t==='c'){// tompa, kerek érme-pöttyenés + halk koppanás az asztalon
    tone(P5[Math.floor(Math.random()*5)]*(den>=2?1.5:1),t,.045,.16,1800);noise(t,700,.7,.02,.05,'lowpass')}
  else{// papírpénz-suhogás + halk mély koppanás
    noise(t,1600+Math.random()*500,.9,.05,.09);tone(196,t,.025,.08,600)}
  if(crit){[523.25,659.25,783.99].forEach((f,k)=>tone(f,t+.05+k*.05,.04,.45,1500))}}
function tkKaching(){if(!SOUND||!ac())return;const a=AC,t=a.currentTime;
  // mély pénztárfiók-„kacc”: fiókhúzás zaj + puha mély ütés + lágy harangszó
  const n=a.createBufferSource();n.buffer=NOISE;const f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=1100;const g=a.createGain();g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.09,t+.03);g.gain.exponentialRampToValueAtTime(.0001,t+.22);n.connect(f).connect(g).connect(MASTER);n.start(t,0,.25);
  const o=a.createOscillator(),og=a.createGain();o.type='sine';o.frequency.setValueAtTime(140,t+.18);o.frequency.exponentialRampToValueAtTime(70,t+.34);og.gain.setValueAtTime(.0001,t+.18);og.gain.exponentialRampToValueAtTime(.14,t+.19);og.gain.exponentialRampToValueAtTime(.0001,t+.4);o.connect(og).connect(MASTER);o.start(t+.18);o.stop(t+.45);
  [[784,.22],[1175,.3]].forEach(([fr,d])=>{const b=a.createOscillator(),bg=a.createGain();b.type='sine';b.frequency.value=fr;bg.gain.setValueAtTime(.0001,t+d);bg.gain.exponentialRampToValueAtTime(.045,t+d+.01);bg.gain.exponentialRampToValueAtTime(.0001,t+d+.8);b.connect(bg).connect(MASTER);b.start(t+d);b.stop(t+d+.85)})}
const TK_CH=[[48,[60,64,67,71]],[45,[57,60,64,67]],[50,[62,65,69,72]],[43,[55,59,62,65]]];// Cmaj7 – Am7 – Dm7 – G7
const tkHz=m=>440*Math.pow(2,(m-69)/12);
function tkMusic(on){if(!on){clearInterval(TK.musI);TK.musI=null;if(TK.musG){try{TK.musG.gain.setTargetAtTime(0,AC.currentTime,.2)}catch(e){}}return}
  if(TK.musI||!ac())return;TK.musG=AC.createGain();TK.musG.gain.value=.55;TK.musG.connect(MASTER);TK.mt=AC.currentTime+.1;TK.mb=0;
  TK.musI=setInterval(()=>{if(!AC||!TK.run)return;if(!SOUND){TK.mt=AC.currentTime+.1;return}const bpm=TK.rush>0?132:104,q=60/bpm;
    while(TK.mt<AC.currentTime+.35){const beat=TK.mb%16,bar=Math.floor(TK.mb/16)%4,[bass,ch]=TK_CH[bar],t=TK.mt,sw=(beat%2)?q*.18:0,tt=t+sw;
      // sétáló basszus negyedekre
      if(beat%4===0){const st=[0,7,12,7][beat/4],o=AC.createOscillator(),g=AC.createGain();o.type='triangle';o.frequency.value=tkHz(bass+st-12);g.gain.setValueAtTime(.0001,tt);g.gain.exponentialRampToValueAtTime(.16,tt+.01);g.gain.exponentialRampToValueAtTime(.0001,tt+q*.95);o.connect(g).connect(TK.musG);o.start(tt);o.stop(tt+q)}
      // elektromos zongora-akkord a 2. és 4. negyedre
      if(beat===4||beat===12)for(const m of ch){const o=AC.createOscillator(),o2=AC.createOscillator(),g=AC.createGain();o.type='sine';o2.type='sine';o.frequency.value=tkHz(m);o2.frequency.value=tkHz(m)*2.003;g.gain.setValueAtTime(.0001,tt);g.gain.exponentialRampToValueAtTime(.022,tt+.01);g.gain.exponentialRampToValueAtTime(.0001,tt+q*1.6);o.connect(g);o2.connect(g);g.connect(TK.musG);o.start(tt);o2.start(tt);o.stop(tt+q*1.7);o2.stop(tt+q*1.7)}
      // swinges cin nyolcadokra
      if(beat%2===0||Math.random()<.3){const n=AC.createBufferSource();n.buffer=NOISE;const f=AC.createBiquadFilter();f.type='highpass';f.frequency.value=7500;const g=AC.createGain();g.gain.setValueAtTime(beat%4===2?.05:.025,tt);g.gain.exponentialRampToValueAtTime(.0001,tt+.05);n.connect(f).connect(g).connect(TK.musG);n.start(tt,Math.random()*.5,.06)}
      // csilingelő harang-arpeggio (kaszinó)
      if(Math.random()<(TK.rush>0?.5:.25)){const m=ch[Math.floor(Math.random()*4)]+12,o=AC.createOscillator(),o2=AC.createOscillator(),g=AC.createGain();o.type='sine';o2.type='sine';o.frequency.value=tkHz(m);o2.frequency.value=tkHz(m)*2;g.gain.setValueAtTime(.0001,tt);g.gain.exponentialRampToValueAtTime(.018,tt+.02);g.gain.exponentialRampToValueAtTime(.0001,tt+.6);o.connect(g);o2.connect(g);g.connect(TK.musG);o.start(tt);o2.start(tt);o.stop(tt+.65);o2.stop(tt+.65)}
      TK.mt+=q/4;TK.mb++}},90)}
