  const gin=a.createGain();gin.gain.value=.9;const hp=a.createBiquadFilter();hp.type='highpass';hp.frequency.value=90;
  const sh=a.createWaveShaper(),cu=new Float32Array(2048);for(let i=0;i<2048;i++){const x=i/1024-1;cu[i]=Math.tanh(x*22)*.9}sh.curve=cu;sh.oversample='2x';
