  const sc=a.createBiquadFilter();sc.type='peaking';sc.frequency.value=380;sc.Q.value=1.2;sc.gain.value=-4;
  const cab=a.createBiquadFilter();cab.type='lowpass';cab.frequency.value=3600;cab.Q.value=.8;
  const gg=a.createGain();gg.gain.value=.16;gin.connect(hp).connect(sh).connect(sc).connect(mid).connect(cab).connect(gg).connect(out);
  const bass=a.createGain();bass.gain.value=.28;const blp=a.createBiquadFilter();blp.type='lowpass';blp.frequency.value=700;bass.connect(blp).connect(out);
