  if(T.shell){c.fillStyle='#b07a3a';c.fillRect(-w/2,h/2-h*.2,w,h*.05);c.fillStyle=T.col;c.beginPath();c.moveTo(-w/2,h/2);c.lineTo(-w/2,-h/2+h*.38);c.quadraticCurveTo(-w/2,-h/2+h*.08,0,-h/2+h*.04);c.quadraticCurveTo(w/2,-h/2+h*.08,w/2,-h/2+h*.38);c.lineTo(w/2,h/2);c.closePath();c.fill();
    c.fillStyle='#d9c040';c.fillRect(-w/2,-h/2+h*.42,w,h*.04);c.fillStyle='#b07a3a';c.fillRect(-w/2,h/2-h*.18,w,h*.05);c.fillStyle='#8a8a80';c.fillRect(-w*.22,-h/2,w*.44,h*.06);c.restore();return}
  if(T.sack){c.fillStyle=T.col;c.beginPath();c.ellipse(0,0,w/2,h/2,0,0,7);c.fill();c.strokeStyle='rgba(0,0,0,.25)';c.stroke();c.fillStyle='#7a6740';c.fillRect(w/2-.08*s,-h*.2,.06*s,h*.4);c.restore();return}
  c.fillStyle=T.col;c.fillRect(-w/2,-h/2,w,h);c.strokeStyle='rgba(0,0,0,.5)';c.lineWidth=1.5;c.strokeRect(-w/2+.75,-h/2+.75,w-1.5,h-1.5);
  if(k==='lad'){c.fillStyle='#3a4420';c.fillRect(-w*.3,-h/2-.03*s,w*.6,.04*s);c.fillRect(w/2-.06*s,-h*.2,.04*s,h*.4);c.restore();return}
  c.strokeStyle='rgba(255,255,255,.12)';c.beginPath();c.moveTo(-w/2+3,-h/2+3);c.lineTo(w/2-3,h/2-3);c.moveTo(w/2-3,-h/2+3);c.lineTo(-w/2+3,h/2-3);c.stroke();
  if(k==='epal'||k==='viz'||k==='lsz'){c.fillStyle='#8a6a3e';c.fillRect(-w/2,h/2-h*.18,w,h*.18);c.fillStyle='#5a4426';for(let i=0;i<3;i++)c.fillRect(-w/2+i*(w-.1*s)/2,h/2-h*.12,.1*s,h*.08)}
