function seFmt(v){v=Number(v)||0;const d=Math.floor(v/100000),p=v%100000,L=['–','Alpha','Bravo I','Bravo II','Charlie','🚁 Kimentve'];return (L[d]||d+' nap')+' · '+n0(p)+' p'}
const seShuf=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const seH=i=>{const v=Math.sin(i*127.1+311.7)*43758.5453;return v-Math.floor(v)};
