  const [px,py]=P(T.x,T.y),pa=T.pa||-Math.PI/2;if(SE.buddy){const [bx,by]=P(T.bx||T.x,T.by||T.y+.8);seTDMan(c,bx,by,T.ba||pa,k,'#55603f','me',T.t*5)}seTDMan(c,px,py,pa,k,'#6a7a45','me',T.tx!=null?T.t*9:0);
