    if(prevTod<.52&&SE.tod>=.52&&SE.day>=2&&!SE.esc){SE.banner={t:0,a:'🌙 ÉJSZAKA',b:'Fedezékről fedezékre!',c:'Az őrök látnak és hallanak – a futás zajos'}}
