  if(hit){M.hits++;seOk();for(let i=0;i<10;i++)SE.fx.push({k:'spark',x:SE.campX-.6+(Math.random()-.5)*.3,y:.2,vx:(Math.random()-.5)*2,vy:1+Math.random()*2,t:0,life:.6});M.zc=.25+Math.random()*.5}else seBeep(240,.08,.04);
