/* ===== Frissítés (PWA) ===== */
let UPD_REG = null, UPD_WAITING = false;
function updSetUI(state, pct, text){
  const btn = document.getElementById('updBtn');
  const prog = document.getElementById('updProg');
  const bar = document.getElementById('updBar');
  const pctEl = document.getElementById('updPct');
  if(!btn) return;
  btn.classList.remove('has-update','updating');
  if(prog) prog.classList.remove('on');
  if(pctEl) pctEl.classList.remove('on');
  if(state === 'available'){
    btn.classList.add('has-update');
    btn.innerHTML = '<span class="ui">!</span><span class="ut">ÚJ VERZIÓ</span>';btn.title='Új verzió elérhető – koppints a telepítéshez';
    btn.disabled = false;
  } else if(state === 'checking'){
    btn.classList.add('updating');
    btn.innerHTML = '<span class="ui spin">⟳</span><span class="ut">KERESÉS…</span>';
    btn.disabled = true;
  } else if(state === 'downloading'){
    btn.classList.add('updating');
    btn.innerHTML = '<span class="ui spin">⟳</span><span class="ut">'+(pct||0)+'%</span>';
    btn.disabled = true;
    if(prog) prog.classList.add('on');
    if(bar) bar.style.width = (pct||0) + '%';
    if(pctEl){ pctEl.classList.add('on'); pctEl.textContent = (pct||0) + '% · ' + (text||''); }
  } else if(state === 'ready'){
    btn.classList.add('has-update');
    btn.innerHTML = '<span class="ui">⬇</span><span class="ut">TELEPÍTÉS</span>';
    btn.disabled = false;
  } else {
    btn.innerHTML = '<span class="ui">⟳</span><span class="ut">FRISSÍTÉS</span>';btn.title='Frissítés ellenőrzése';
    btn.disabled = false;
  }
}
async function updCheck(){
  if(!UPD_REG){ if(typeof toast==='function') toast('Frissítés csak HTTPS-en / telepített appban működik.'); return; }
  updSetUI('checking');
  try{ await UPD_REG.update(); }catch(e){}
  setTimeout(()=>{
    if(!UPD_WAITING){
      updSetUI('idle');
      if(typeof toast==='function') toast('Nincs újabb verzió. A legfrissebb fut.');
    }
  }, 1500);
}
// automatikus frissítés: ha nincs nyitva játék, azonnal; játék közben a játék bezárásakor vagy amikor az app háttérbe kerül
let UPD_AUTO_TOLD=false;
function updGameOpen(){const h=document.getElementById('harc');return !!(h&&!h.hidden)}
function updAuto(){if(!UPD_REG||!UPD_REG.waiting)return;
  if(typeof SR!=='undefined'&&SR.net&&updGameOpen())return;// futó online párbajt nem szakítunk meg
  if(updGameOpen()&&!document.hidden){if(!UPD_AUTO_TOLD&&typeof toast==='function'){UPD_AUTO_TOLD=true;toast('✨ Új verzió letöltve – a játék bezárásakor automatikusan frissül.')}return}
  try{if(typeof seSave==='function')seSave()}catch(e){}
  try{localStorage.setItem('medve-upd-from',APP_VER)}catch(e){}
  if(typeof toast==='function'&&!document.hidden)toast('✨ Új verzió – frissítés…');
  UPD_REG.waiting.postMessage({ type: 'SKIP_WAITING' });updSetUI('downloading',100,'Telepítés…')}
(()=>{const h=document.getElementById('harc');if(h)new MutationObserver(()=>{if(h.hidden){if(UPD_WAITING)setTimeout(updAuto,400);else swUpd(UPD_REG)}}).observe(h,{attributes:true,attributeFilter:['hidden']});
  try{const f=localStorage.getItem('medve-upd-from');if(f){localStorage.removeItem('medve-upd-from');if(f!==APP_VER)setTimeout(()=>{if(typeof toast==='function')toast('✅ Frissítve: v'+f+' → v'+APP_VER)},1200)}}catch(e){}})();
function updApply(){
  if(UPD_REG && UPD_REG.waiting){
    UPD_REG.waiting.postMessage({ type: 'SKIP_WAITING' });
    updSetUI('downloading', 100, 'Telepítés…');
  } else {
    updCheck();
  }
}
if('serviceWorker' in navigator && (location.protocol === 'https:' || location.hostname === 'localhost')){
  navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(reg => {
    UPD_REG = reg;
    if(reg.waiting){ UPD_WAITING = true; updSetUI('available'); updAuto(); }
    // csendes ellenőrzés: induláskor, 15 percenként és amikor visszatérsz az appba
    // automatikus frissítés: indításkor azonnal, utána 2 percenként, valamint előtérbe kerüléskor és játék bezárásakor keres új verziót
    swUpd(reg);
    setInterval(()=>{ if(!document.hidden) swUpd(reg); }, 2*60*1000);
    addEventListener('focus', ()=>swUpd(reg));addEventListener('pageshow', ()=>swUpd(reg));
    document.addEventListener('visibilitychange', ()=>{ if(!document.hidden) swUpd(reg); else updAuto(); });
    reg.addEventListener('updatefound', () => {
      const nw = reg.installing;
      if(!nw) return;
      updSetUI('downloading', 0, 'Letöltés indul…');
      nw.addEventListener('statechange', () => {
        if(nw.state === 'installed'){
          if(navigator.serviceWorker.controller){
            UPD_WAITING = true;
            updSetUI('available');
            updAuto();
          } else {
            updSetUI('idle');
          }
        }
      });
    });
  }).catch(()=>{});
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if(UPD_WAITING) location.reload();
  });
  navigator.serviceWorker.addEventListener('message', e => {
    if(e.data && e.data.type === 'UPDATE_PROGRESS'){
      updSetUI('downloading', e.data.pct, e.data.text || '');
      if(e.data.pct >= 100) setTimeout(() => { if(UPD_WAITING) updSetUI('available'); else updSetUI('idle'); }, 600);
    }
  });
}
document.addEventListener('click', e => {
  if(e.target && e.target.closest && e.target.closest('#updBtn')){
    if(UPD_WAITING) updApply(); else updCheck();
  }
});
