const MERR={seen:{},n:0};
let SWUPD_T=0;
function swUpd(r){try{const n=Date.now();if(n-SWUPD_T<20000)return;SWUPD_T=n;if(r&&navigator.onLine)r.update().catch(e=>console.warn('SW frissítés-ellenőrzés kihagyva:',e&&e.message))}catch(e){}}
function medveErr(e,game){try{const msg=String(e&&e.message||e||'ismeretlen hiba');if(/ResizeObserver|Script error|extension/i.test(msg))return;
  const st=String(e&&e.stack||''),fn=(st.split('\n').map(l=>l.trim()).find(l=>/^at /.test(l))||'').replace(/^at /,'').replace(/\(.*?:(\d+):\d+\)/,'@$1').slice(0,60);
  let h=0;for(const ch of msg+fn)h=(h*31+ch.charCodeAt(0))>>>0;const code=(game||'APP').slice(0,3).toUpperCase().replace(/[^A-Z]/g,'X')+'-'+(h%65536).toString(16).toUpperCase().padStart(4,'0');
  MERR.n++;const rec=MERR.seen[code]=(MERR.seen[code]||{n:0});rec.n++;
  try{const lg=JSON.parse(localStorage.getItem('medve-errlog')||'[]');lg.unshift({code,game,msg,fn,v:APP_VER,t:new Date().toISOString()});localStorage.setItem('medve-errlog',JSON.stringify(lg.slice(0,15)))}catch(_){}
  if(rec.n>1&&rec.shown){const c=document.querySelector('#errBox .ecnt');if(c)c.textContent='×'+rec.n;return}rec.shown=1;
  let b=document.getElementById('errBox');if(!b){b=document.createElement('div');b.id='errBox';b.style.cssText='position:fixed;left:10px;right:10px;top:calc(env(safe-area-inset-top,0px) + 8px);z-index:99999;background:#2a0d0b;border:2px solid #ff5a4a;border-radius:14px;padding:12px 14px;color:#ffe9e4;font:600 14px/1.35 system-ui,sans-serif;box-shadow:0 8px 30px rgba(0,0,0,.6)';document.body.appendChild(b)}
  const txt=`M.E.D.V.E. Arcade ${APP_VER} · ${game} · ${code}\n${msg}\n${fn}`;
  b.innerHTML=`<div data-st="display:flex;justify-content:space-between;gap:8px;align-items:center"><b data-st="font-size:15px">⚠ Hiba történt · <span data-st="color:#ffd24a">${code}</span> <span class="ecnt"></span></b><button data-x data-st="background:none;border:0;color:#fff;font-size:20px">✕</button></div><div data-st="margin:6px 0 8px;font-weight:500;opacity:.9">${game}: ${esc(msg)}<br><small data-st="opacity:.7">${esc(fn)}</small><br>A játék megpróbál tovább futni. Küldd el a kódot a fejlesztőnek.</div><button data-c data-st="background:#ff5a4a;color:#fff;border:0;border-radius:9px;padding:7px 12px;font-weight:800">📋 Kód másolása</button> <button data-x data-st="background:#4a2420;color:#fff;border:0;border-radius:9px;padding:7px 12px;font-weight:700">Bezár</button>`;
  b.hidden=false;b.querySelectorAll('[data-x]').forEach(x=>x.onclick=()=>{b.hidden=true});b.querySelector('[data-c]').onclick=()=>{try{navigator.clipboard.writeText(txt);toast('Hibakód kimásolva')}catch(_){}};
  clearTimeout(MERR.to);MERR.to=setTimeout(()=>{b.hidden=true},20000)}catch(_){}}
window.addEventListener('error',ev=>medveErr(ev.error||ev.message,'APP'));
